digits-module-gold.digits.c:
#include "digits.h"
int digitSum(int n){int s=0;do{s+=n%10;n/=10;}while(n);return s;}
int digitCount(int n){int k=0;do{k++;n/=10;}while(n);return k;}

recursive-power.main.c:
#include <stdio.h>
int power(int x,int n){if(!n)return 1;return x*power(x,n-1);}
int main(void){int x,n;if(scanf("%d %d",&x,&n)!=2)return 1;printf("power=%d\n",power(x,n));return 0;}

recursive-power-gold.main.c:
#include <stdio.h>
int fastPower(int x,int n,int *calls){(*calls)++;if(!n)return 1;int half=fastPower(x,n/2,calls),result=half*half;return n%2?result*x:result;}
int main(void){int x,n,calls=0;if(scanf("%d %d",&x,&n)!=2)return 1;int v=fastPower(x,n,&calls);printf("power=%d calls=%d\n",v,calls);return 0;}
